        // Accept `req.originalUrl` for expressjs usage.
        // https://expressjs.com/en/api.html#req.originalUrl
        url: req.originalUrl || req.url,
        headers: req.headers,
        remoteAddress: req.connection.remoteAddress,
        remotePort: req.connection.remotePort
